const root = document.querySelector("#app");
const toast = document.querySelector("#toast");
// The frontend dev server is a separate process and does not proxy /api.
// Use the backend port for any standalone frontend port; same-origin when
// the app is served by the API itself. Deployments can override this value.
const API = window.BAKERY_API_BASE_URL ?? (location.port === "5000" ? "" : `${location.protocol}//${location.hostname}:5000`);
const today = () => new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Kolkata", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date());
const initialParams = new URLSearchParams(location.search);
const validPages = new Set(["dashboard", "orders", "payments", "shops", "routes", "products", "salesmen", "attendance", "reports", "production", "materials"]);
function pageFromLocation() {
  const queryPage = new URLSearchParams(location.search).get("page");
  const pathPage = location.pathname.split("/").filter(Boolean)[0];
  const candidate = queryPage || pathPage || "dashboard";
  return validPages.has(candidate) ? candidate : "dashboard";
}
const state = { token: localStorage.getItem("bakery_admin_token"), user: null, page: pageFromLocation(), day: initialParams.get("date") || today(), data: null, routes: [], reportSort: null };
const money = (n) => new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(Number(n) || 0);
const esc = (v = "") => String(v).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const shortDate = (v) => v ? new Date(v).toLocaleString("en-IN", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }) : "—";
const num = (v) => Number(v || 0).toLocaleString("en-IN");

async function api(path, options = {}) {
  const response = await fetch(`${API}${path}`, { ...options, headers: { ...(options.body ? { "Content-Type": "application/json" } : {}), ...(state.token ? { Authorization: `Bearer ${state.token}` } : {}), ...options.headers } });
  if (response.status === 401 && state.token) logout(false);
  if (!response.ok) {
    const result = await response.json().catch(() => ({}));
    throw new Error(result.message || `Request failed (${response.status})`);
  }
  return response.headers.get("content-type")?.includes("application/json") ? response.json() : response.blob();
}

function notify(message) {
  toast.textContent = message;
  toast.classList.add("show");
  window.setTimeout(() => toast.classList.remove("show"), 2800);
}

function login(error = "") {
  root.innerHTML = `<section class="login-shell"><div class="login-art"><div class="art-bread">🥐</div><div class="art-copy"><div class="eyebrow">Bakery operations</div><h1>Everything<br>fresh, in sync.</h1><p>Sales, collections, routes and daily operations in one admin workspace.</p></div></div><div class="login-area"><form class="login-card" id="login-form"><div class="brand"><span class="brand-mark">✳</span> crumb & co.</div><h2>Admin sign in</h2><p class="subtle">Sign in with your administrator account.</p><div class="field"><label for="identity">Email or phone</label><input id="identity" autocomplete="username" placeholder="you@yourbakery.com or phone" required maxlength="254"></div><div class="field"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" placeholder="Enter your password" required maxlength="128"></div>${error ? `<p class="error">${esc(error)}</p>` : ""}<button class="primary" type="submit">Sign in to admin</button><p class="login-note">This workspace is for bakery administrators. Sales accounts cannot access the admin app.</p></form></div></section>`;
  root.querySelector("#login-form").addEventListener("submit", async (event) => {
    event.preventDefault(); const button = event.currentTarget.querySelector("button"); button.disabled = true; button.textContent = "Signing in…";
    const identity = root.querySelector("#identity").value.trim();
    try {
      const result = await api("/api/auth/admin-login", { method: "POST", body: JSON.stringify({ ...(identity.includes("@") ? { email: identity } : { phone: identity }), password: root.querySelector("#password").value }) });
      state.token = result.token; localStorage.setItem("bakery_admin_token", result.token); state.user = result.user; await initialize();
    } catch (err) { login(err.message); }
  });
}

function logout(message = true) {
  localStorage.removeItem("bakery_admin_token"); state.token = null; state.user = null; state.data = null; login(); if (message) notify("You have been signed out");
}

async function initialize() {
  try {
    const { user } = await api("/api/auth/me");
    if (user.role !== "owner") throw new Error("This admin workspace is only available to bakery administrators.");
    state.user = user; await loadRoutes(); shell(); await loadPage();
  } catch (err) { localStorage.removeItem("bakery_admin_token"); state.token = null; login(err.message); }
}

async function loadRoutes() { try { const result = await api("/api/admin/routes"); state.routes = result.routes || []; } catch { state.routes = []; } }

const navItems = [
  ["dashboard", "⌂", "Dashboard"], ["orders", "▤", "Orders"], ["payments", "₹", "Payments & dues"],
  ["shops", "⌖", "Shops"], ["routes", "⇢", "Routes"], ["products", "▦", "Products"],
  ["salesmen", "♙", "Salesmen"], ["attendance", "◷", "Attendance"], ["reports", "▥", "Reports"],
  ["production", "♨", "Factory plan"], ["materials", "◫", "Raw materials"],
];

function shell() {
  root.innerHTML = `<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-mark">✳</span> crumb & co.</div><div class="nav-label">Admin workspace</div><nav class="nav">${navItems.map(([id, icon, label]) => `<button data-page="${id}" class="${state.page === id ? "active" : ""}"><span class="nav-icon">${icon}</span>${label}</button>`).join("")}</nav><div class="side-bottom"><div class="profile"><div class="avatar">${esc((state.user?.name || "A").slice(0, 1).toUpperCase())}</div><div><strong>${esc(state.user?.name || "Administrator")}</strong><small>Owner · Admin</small></div><button class="logout" title="Sign out" aria-label="Sign out">↪</button></div></div></aside><section class="main"><header class="topbar"><div class="greeting"><h1 id="page-title">Dashboard</h1><p id="page-subtitle">Your bakery at a glance.</p></div><div class="header-actions"><label class="date-chip">Date <input id="global-date" type="date" value="${esc(state.day)}"></label><button class="logout mobile-logout" aria-label="Sign out" title="Sign out">↪</button></div></header><div id="page-content"><div class="loading">Loading admin workspace…</div></div></section></div>`;
  root.querySelectorAll("[data-page]").forEach((button) => button.addEventListener("click", () => navigate(button.dataset.page)));
  root.querySelectorAll(".logout").forEach((button) => button.addEventListener("click", () => logout()));
  root.querySelector("#global-date").addEventListener("change", (event) => { state.day = event.target.value || today(); const url = new URL(location.href); url.searchParams.set("date", state.day); history.replaceState({}, "", url); loadPage(); });
}

function navigate(page, params = {}) {
  state.page = page;
  const url = new URL(location.href); url.searchParams.set("page", page);
  for (const [key, value] of Object.entries(params)) value ? url.searchParams.set(key, value) : url.searchParams.delete(key);
  history.pushState({}, "", url);
  shell(); loadPage();
}

window.addEventListener("popstate", () => { const url = new URL(location.href); state.page = pageFromLocation(); state.day = url.searchParams.get("date") || today(); shell(); loadPage(); });

async function loadPage() {
  const titles = { dashboard: ["Dashboard", "Your bakery at a glance."], orders: ["Orders", "Find, review and print bakery orders."], payments: ["Payments & dues", "Collections received and shops with outstanding balances."], shops: ["Shops", "Manage customers, route assignments and locations."], routes: ["Routes", "Organize delivery and salesman routes."], products: ["Products", "Manage your bakery catalog, pricing and display order."], salesmen: ["Salesmen", "Team accounts, route assignments and targets."], attendance: ["Attendance", "Daily check-ins, hours and starting locations."], reports: ["Reports", "Explore performance and export a clean report."], production: ["Factory plan", "Compare planned and actual production."], materials: ["Raw materials", "Track ingredients against minimum levels."] };
  const [title, subtitle] = titles[state.page] || titles.dashboard;
  root.querySelector("#page-title").textContent = title; root.querySelector("#page-subtitle").textContent = subtitle;
  const content = root.querySelector("#page-content"); content.innerHTML = `<div class="loading">Loading ${esc(title.toLowerCase())}…</div>`;
  try {
    if (state.page === "dashboard") { state.data = await api(`/api/admin/dashboard?date=${encodeURIComponent(state.day)}`); content.innerHTML = dashboardHtml(state.data); bindDashboard(); }
    else if (state.page === "orders") await renderOrders(content);
    else if (state.page === "payments") await renderPayments(content);
    else if (["shops", "routes", "products", "salesmen"].includes(state.page)) await renderDirectory(content, state.page);
    else if (state.page === "attendance") await renderAttendance(content);
    else if (state.page === "reports") await renderReports(content);
    else if (state.page === "production") await renderProduction(content);
    else if (state.page === "materials") await renderMaterials(content);
    bindShared();
  } catch (err) { content.innerHTML = `<section class="panel error-panel"><strong>Could not load this view</strong><p>${esc(err.message)}</p><button class="secondary" data-reload>Try again</button></section>`; content.querySelector("[data-reload]").addEventListener("click", loadPage); }
}

function dashboardHtml(d) {
  const h = d.headline;
  const change = h.salesChangePercent === null ? "No sales yesterday" : `${h.salesChangePercent >= 0 ? "↑" : "↓"} ${Math.abs(h.salesChangePercent)}% vs previous day`;
  const chartMax = Math.max(1, ...d.chart.map((x) => x.sales));
  const chart = d.chart.map((point, i) => { const height = Math.max(4, point.sales / chartMax * 120); return `<g><rect x="${i * 84 + 18}" y="${140 - height}" width="42" height="${height}" rx="7" fill="${i === 6 ? "#d97743" : "#f0d7c8"}"><title>${esc(point.date)} · ${money(point.sales)}</title></rect><text x="${i * 84 + 39}" y="158" text-anchor="middle">${new Date(`${point.date}T12:00:00`).toLocaleDateString("en-IN", { day: "numeric", month: "short" })}</text></g>`; }).join("");
  return `<div class="stats">${statCard("Sales", money(h.sales), "₹", change, h.salesChangePercent >= 0)}${statCard("Orders", num(h.orderCount), "▤", `On ${esc(d.date)}`)}${statCard("Collected", money(h.collected), "◉", `Cash ${money(h.cash)} · UPI ${money(h.upi)}`)}${statCard("Salesmen working", `${h.salesmenStarted}/${h.activeSalesmen}`, "♙", "Started attendance today")}</div><div class="section-title"><div><h2>Sales · last 7 days</h2><p>Ending ${esc(d.date)} · cancelled orders excluded</p></div></div><section class="panel chart-panel"><svg viewBox="0 0 600 175" role="img" aria-label="Sales for the last seven days"><line x1="0" y1="140" x2="600" y2="140" stroke="#eae8e1"/>${chart}</svg></section><div class="two-col"><section><div class="section-title"><div><h2>Salesmen today</h2><p>Click a row to view that day's orders</p></div><button class="action" data-go="attendance">Attendance →</button></div><div class="panel table-wrap">${salesmenTable(d.salesmen)}</div></section><section><div class="section-title"><div><h2>Top products</h2><p>By quantity · selected day</p></div><button class="action" data-go="reports">Reports →</button></div><div class="panel">${d.topProducts.length ? `<table><thead><tr><th>Product</th><th>Qty</th><th>Sales</th></tr></thead><tbody>${d.topProducts.map((p) => `<tr><td class="product-name">${esc(p.name)}</td><td>${num(p.quantity)}</td><td>${money(p.sales)}</td></tr>`).join("")}</tbody></table>` : empty("No orders on this date")}</div></section></div><div class="section-title"><div><h2>Latest orders</h2><p>Ten most recent orders for the selected day</p></div><button class="action" data-go="orders">All orders →</button></div><section class="panel table-wrap">${ordersTable(d.latestOrders)}</section><div class="section-title"><div><h2>Factory snapshot</h2><p>Production and stock signals · ${esc(d.date)}</p></div></div><div class="stats factory-stats"><button class="stat link-stat" data-go="production"><div class="stat-head">Baked / plan <span class="stat-icon">♨</span></div><div class="stat-value">${num(d.factory.baked)} / ${num(d.factory.planned)}</div><div class="stat-foot">Today's production</div></button>${linkStat("Wastage", `${d.factory.wastagePercent}%`, "⌁", "Of baked + wasted units", "production")}${linkStat("Low stock products", num(d.factory.lowStockProducts.length), "◫", "Review product stock", "products")}${linkStat("Raw materials low", num(d.factory.rawMaterialsBelowMinimum.length), "◉", "Below minimum level", "materials")}</div><div class="quick-actions"><button class="quick-action" data-go="products"><span>▦</span><strong>Products</strong><small>Catalog and stock</small></button><button class="quick-action" data-go="materials"><span>◫</span><strong>Raw materials</strong><small>Minimum levels</small></button></div>`;
}

function statCard(title, value, icon, foot, good = false) { return `<article class="stat"><div class="stat-head">${title}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot ${good ? "good" : ""}">${foot || ""}</div></article>`; }
function linkStat(title, value, icon, foot, page) { return `<button class="stat link-stat" data-go="${page}"><div class="stat-head">${title}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></button>`; }
function empty(message) { return `<div class="empty">${esc(message)}</div>`; }
function salesmenTable(rows) { return rows.length ? `<table><thead><tr><th>Salesman</th><th>Started</th><th>Shops</th><th>Sales</th><th>Collected</th></tr></thead><tbody>${rows.map((u) => `<tr class="clickable" data-salesman="${u.id}"><td class="product-name">${esc(u.name)}</td><td>${shortDate(u.startedAt)}</td><td>${u.shopsVisited}/${u.shopsOnRoute}</td><td>${money(u.sales)}</td><td>${money(u.collected)}</td></tr>`).join("")}</tbody></table>` : empty("No salesmen assigned") ; }
function ordersTable(rows) { return rows.length ? `<table><thead><tr><th>Bill no.</th><th>Date / time</th><th>Shop</th><th>Route</th><th>Salesman</th><th>Items</th><th>Total</th><th>Paid / due</th><th>Status</th></tr></thead><tbody>${rows.map((o) => `<tr class="clickable" data-order="${o._id}"><td class="product-name">${esc(o.billNo)}</td><td>${shortDate(o.createdAt)}</td><td>${esc(o.shopSnapshot?.name || o.shop?.name || "—")}</td><td>${esc(o.routeSnapshot || o.route?.name || "—")}</td><td>${esc(o.salesman?.name || "—")}</td><td>${num(o.itemsCount)}</td><td>${money(o.total)}</td><td>${money(o.paid)} / ${money(Math.max(0, o.total - o.paid))}</td><td><span class="pill ${o.status === "cancelled" ? "low" : ""}">${esc(o.status)}</span></td></tr>`).join("")}</tbody></table>` : empty("No orders match those filters"); }

function bindDashboard() {
  root.querySelectorAll("[data-order]").forEach((row) => row.addEventListener("click", () => showOrder(row.dataset.order)));
  root.querySelectorAll("[data-salesman]").forEach((row) => row.addEventListener("click", () => navigate("orders", { salesman: row.dataset.salesman, from: state.day, to: state.day })));
}

function queryUrl(page, extras = {}) { const params = new URLSearchParams(); const url = new URL(location.href); for (const key of ["from", "to", "salesman", "route", "shop", "status", "page", "sort", "mode", "report"]) { const value = extras[key] ?? url.searchParams.get(key); if (value) params.set(key, value); } return `/${page}?${params.toString()}`; }

async function renderOrders(content) {
  const q = new URLSearchParams(location.search); const query = new URLSearchParams();
  for (const key of ["from", "to", "salesman", "route", "shop", "status", "page"]) if (q.get(key)) query.set(key, q.get(key));
  if (!query.has("from")) query.set("from", state.day);
  if (!query.has("to")) query.set("to", state.day);
  const [result, salesmen, routes] = await Promise.all([api(`/api/orders?${query}`), api("/api/admin/salesmen"), api("/api/admin/routes")]);
  state.routes = routes.routes;
  content.innerHTML = `<form class="panel filters" id="order-filters"><label>From<input type="date" name="from" value="${esc(q.get("from") || state.day)}"></label><label>To<input type="date" name="to" value="${esc(q.get("to") || state.day)}"></label><label>Salesman<select name="salesman"><option value="">All salesmen</option>${salesmen.salesmen.map((u) => `<option value="${u._id}" ${q.get("salesman") === u._id ? "selected" : ""}>${esc(u.name)}</option>`).join("")}</select></label><label>Route<select name="route"><option value="">All routes</option>${routes.routes.map((r) => `<option value="${r._id}" ${q.get("route") === r._id ? "selected" : ""}>${esc(r.name)}</option>`).join("")}</select></label><label>Shop<input name="shop" placeholder="Search shop" value="${esc(q.get("shop") || "")}"></label><label>Status<select name="status"><option value="">All statuses</option>${["open", "paid", "cancelled"].map((v) => `<option ${q.get("status") === v ? "selected" : ""}>${v}</option>`).join("")}</select></label><button class="primary">Apply filters</button><button class="secondary" type="button" data-clear-filters>Clear</button></form><div class="section-title"><div><h2>${num(result.pagination.total)} orders</h2><p>Cancelled orders remain in history and are excluded from totals.</p></div></div><section class="panel table-wrap">${ordersTable(result.orders)}</section><div class="pagination"><span>Page ${result.pagination.page} of ${Math.max(1, result.pagination.pages)}</span><div><button class="secondary" data-order-page="${Math.max(1, result.pagination.page - 1)}" ${result.pagination.page <= 1 ? "disabled" : ""}>← Previous</button> <button class="secondary" data-order-page="${Math.min(result.pagination.pages || 1, result.pagination.page + 1)}" ${result.pagination.page >= result.pagination.pages ? "disabled" : ""}>Next →</button></div></div>`;
  content.querySelector("#order-filters").addEventListener("submit", (event) => { event.preventDefault(); const params = new URLSearchParams(new FormData(event.currentTarget)); for (const [k,v] of [...params]) if (!v) params.delete(k); params.set("page", "1"); history.pushState({}, "", `/?page=orders&${params}`); loadPage(); });
  content.querySelector("[data-clear-filters]").addEventListener("click", () => { history.pushState({}, "", `/?page=orders&date=${state.day}`); loadPage(); });
  content.querySelectorAll("[data-order]").forEach((row) => row.addEventListener("click", () => showOrder(row.dataset.order)));
  content.querySelectorAll("[data-order-page]").forEach((button) => button.addEventListener("click", () => { const next = new URLSearchParams(location.search); next.set("page", button.dataset.orderPage); history.pushState({}, "", `/?${next}`); loadPage(); }));
}

function showModal(html, onReady = () => {}) { const backdrop = document.createElement("div"); backdrop.className = "modal-backdrop"; backdrop.innerHTML = `<section class="modal modal-wide">${html}</section>`; document.body.append(backdrop); backdrop.addEventListener("click", (e) => { if (e.target === backdrop || e.target.closest("[data-close]")) backdrop.remove(); }); onReady(backdrop); return backdrop; }

async function showOrder(orderId) {
  try {
    const { order } = await api(`/api/orders/${orderId}`);
    const payments = order.payments || [];
    const modal = showModal(`<button class="modal-x" data-close aria-label="Close">×</button><div class="eyebrow">${esc(order.status)} order</div><h2>${esc(order.billNo)}</h2><p class="subtle">${esc(order.shopSnapshot?.name || "Shop")} · ${shortDate(order.createdAt)} · ${esc(order.salesman?.name || "Salesman")}</p><div class="invoice-lines"><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>${order.lines.map((line) => `<tr><td>${esc(line.name)}</td><td>${num(line.quantity)}</td><td>${money(line.unitPrice)}</td><td>${money(line.lineTotal)}</td></tr>`).join("")}</tbody></table></div><div class="bill-total"><span>Total</span><strong>${money(order.total)}</strong><span>Paid ${money(order.paid)} · Due ${money(order.due)}</span></div><div class="section-title"><div><h3>Payments</h3></div></div>${payments.length ? `<table><tbody>${payments.map((p) => `<tr><td>${shortDate(p.receivedAt)}</td><td>${esc(p.mode.toUpperCase())}</td><td>${money(p.amount)}</td></tr>`).join("")}</tbody></table>` : empty("No payments recorded") }<div class="section-title"><div><h3>History</h3></div></div><div class="history-list">${order.history.map((h) => `<div><span>${esc(h.action.replaceAll("_", " "))}</span><small>${shortDate(h.at)} ${h.note ? `· ${esc(h.note)}` : ""}</small></div>`).join("")}</div><div class="modal-actions"><button class="secondary" data-print>Print / save PDF</button><button class="secondary" data-download>Download invoice</button>${order.status !== "cancelled" && order.total > order.paid ? `<button class="secondary" data-collect>Record payment</button>` : ""}${order.status !== "cancelled" ? `<button class="danger" data-cancel>Cancel order</button>` : ""}</div>`);
    modal.querySelector("[data-print]").addEventListener("click", () => printInvoice(order));
    modal.querySelector("[data-download]").addEventListener("click", () => downloadInvoice(order));
    modal.querySelector("[data-cancel]")?.addEventListener("click", () => cancelOrder(order._id, modal));
    modal.querySelector("[data-collect]")?.addEventListener("click", () => paymentModal(order, modal));
  } catch (error) { notify(error.message); }
}

function invoiceHtml(order) {
  const lines = order.lines.map((l) => `<tr><td>${esc(l.name)}<small>${esc(l.sku)}</small></td><td>${num(l.quantity)}</td><td>${money(l.unitPrice)}</td><td>${money(l.lineTotal)}</td></tr>`).join("");
  return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(order.billNo)}</title><link rel="stylesheet" href="${location.origin}/invoice.css"></head><body><div class="head"><div><h1>${esc(document.title.split("|")[0].trim())}</h1><b>Invoice</b></div><div><b>${esc(order.billNo)}</b><br>${shortDate(order.createdAt)}</div></div><p><b>Bill to</b><br>${esc(order.shopSnapshot?.name || "Shop")}<br>${esc(order.shopSnapshot?.address || "")}</p><table><thead><tr><th>Item</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody>${lines}</tbody></table><div class="total">Total ${money(order.total)}</div><p>Paid ${money(order.paid)} · Due ${money(Math.max(0, order.total - order.paid))}</p></body></html>`;
}

function printInvoice(order) {
  const w = window.open("", "_blank", "width=800,height=900"); if (!w) return notify("Allow pop-ups to print this bill");
  w.document.write(invoiceHtml(order)); w.document.close(); window.setTimeout(() => { w.focus(); w.print(); }, 600);
}

function downloadInvoice(order) {
  const link = document.createElement("a");
  link.href = URL.createObjectURL(new Blob([invoiceHtml(order)], { type: "text/html;charset=utf-8" }));
  link.download = `${order.billNo}.html`; link.click(); URL.revokeObjectURL(link.href);
}

function cancelOrder(id) { showModal(`<button class="modal-x" data-close>×</button><h2>Cancel order</h2><p class="subtle">This order will stay in history and stop counting in totals.</p><form id="cancel-form"><div class="field"><label>Reason</label><textarea name="reason" maxlength="300" required></textarea></div><div class="modal-actions"><button class="secondary" type="button" data-close>Keep order</button><button class="danger">Cancel order</button></div></form>`).querySelector("#cancel-form").addEventListener("submit", async (event) => { event.preventDefault(); try { await api(`/api/orders/${id}/cancel`, { method: "POST", body: JSON.stringify({ reason: new FormData(event.currentTarget).get("reason") }) }); document.querySelectorAll(".modal-backdrop").forEach((el) => el.remove()); notify("Order cancelled"); await loadPage(); } catch (error) { notify(error.message); } }); }

function paymentModal(order, parent) { showModal(`<button class="modal-x" data-close>×</button><h2>Record payment</h2><p class="subtle">Remaining due ${money(order.due)}</p><form id="payment-form"><div class="field"><label>Amount (₹)</label><input name="amount" type="number" min="0.01" max="${order.due}" step="0.01" required></div><div class="field"><label>Mode</label><select name="mode"><option value="cash">Cash</option><option value="upi">UPI</option></select></div><div class="field"><label>Note</label><input name="note" maxlength="200"></div><div class="modal-actions"><button class="secondary" type="button" data-close>Cancel</button><button class="primary">Record payment</button></div></form>`).querySelector("#payment-form").addEventListener("submit", async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { await api(`/api/payments/orders/${order._id}`, { method: "POST", body: JSON.stringify({ amount: Number(form.get("amount")), mode: form.get("mode"), note: form.get("note") }) }); parent.remove(); notify("Payment recorded"); await loadPage(); } catch (error) { notify(error.message); } }); }

async function renderPayments(content) {
  const q = new URLSearchParams(location.search); const params = new URLSearchParams(); for (const key of ["from", "to", "salesman", "mode", "page"]) if (q.get(key)) params.set(key, q.get(key));
  if (!params.has("from")) params.set("from", state.day); if (!params.has("to")) params.set("to", state.day);
  const [result, dues, salesmen] = await Promise.all([api(`/api/payments?${params}`), api(`/api/admin/dues?sort=${q.get("sort") === "age" ? "age" : "amount"}`), api("/api/admin/salesmen")]);
  content.innerHTML = `<div class="section-title"><div><h2>Collections</h2><p>Payments posted in the selected date range</p></div></div><form class="panel filters" id="payment-filters"><label>From<input type="date" name="from" value="${esc(q.get("from") || state.day)}"></label><label>To<input type="date" name="to" value="${esc(q.get("to") || state.day)}"></label><label>Salesman<select name="salesman"><option value="">All salesmen</option>${salesmen.salesmen.map((u) => `<option value="${u._id}" ${q.get("salesman") === u._id ? "selected" : ""}>${esc(u.name)}</option>`).join("")}</select></label><label>Mode<select name="mode"><option value="">All</option><option value="cash" ${q.get("mode") === "cash" ? "selected" : ""}>Cash</option><option value="upi" ${q.get("mode") === "upi" ? "selected" : ""}>UPI</option></select></label><button class="primary">Filter</button></form><section class="panel table-wrap">${result.payments.length ? `<table><thead><tr><th>Date</th><th>Bill</th><th>Shop</th><th>Salesman</th><th>Mode</th><th>Amount</th></tr></thead><tbody>${result.payments.map((p) => `<tr><td>${shortDate(p.receivedAt)}</td><td>${esc(p.order?.billNo || "—")}</td><td>${esc(p.shop?.name || "—")}</td><td>${esc(p.salesman?.name || "—")}</td><td><span class="pill">${esc(p.mode.toUpperCase())}</span></td><td>${money(p.amount)}</td></tr>`).join("")}</tbody></table>` : empty("No collections match those filters")}</section><div class="section-title"><div><h2>Shop dues</h2><p>Open balances grouped by the oldest unpaid bill</p></div><select id="dues-sort" class="inline-input"><option value="amount" ${q.get("sort") !== "age" ? "selected" : ""}>Sort by amount</option><option value="age" ${q.get("sort") === "age" ? "selected" : ""}>Sort by age</option></select></div><section class="panel table-wrap">${dues.dues.length ? `<table><thead><tr><th>Shop</th><th>Open bills</th><th>Oldest due</th><th>Age</th><th>Total due</th></tr></thead><tbody>${dues.dues.map((d) => `<tr class="clickable" data-shop-statement="${d.shop._id}"><td class="product-name">${esc(d.shop.name)}</td><td>${d.bills}</td><td>${shortDate(d.oldestDueAt)}</td><td><span class="pill ${d.ageDays > 15 ? "low" : ""}">${d.ageBucket} days</span></td><td>${money(d.due)}</td></tr>`).join("")}</tbody></table>` : empty("No shops currently owe money")}</section>`;
  content.querySelector("#payment-filters").addEventListener("submit", (e) => { e.preventDefault(); const p = new URLSearchParams(new FormData(e.currentTarget)); for (const [k,v] of [...p]) if (!v) p.delete(k); history.pushState({}, "", `/?page=payments&${p}`); loadPage(); });
  content.querySelector("#dues-sort").addEventListener("change", (e) => { const p = new URLSearchParams(location.search); p.set("sort", e.target.value); history.pushState({}, "", `/?${p}`); loadPage(); });
  content.querySelectorAll("[data-shop-statement]").forEach((row) => row.addEventListener("click", () => shopStatement(row.dataset.shopStatement)));
}

async function shopStatement(shopId) { try { const data = await api(`/api/admin/shops/${shopId}/statement`); const { shop } = data; showModal(`<button class="modal-x" data-close>×</button><div class="eyebrow">Shop account</div><h2>${esc(shop.name)}</h2><p class="subtle">${esc(shop.address || "")} · ${esc(shop.route?.name || "Unassigned route")}</p><h3>Orders</h3><div class="table-wrap"><table><thead><tr><th>Bill</th><th>Date</th><th>Total</th><th>Paid</th><th>Due</th></tr></thead><tbody>${data.orders.map((o) => `<tr class="clickable" data-order="${o._id}"><td>${esc(o.billNo)}</td><td>${shortDate(o.createdAt)}</td><td>${money(o.total)}</td><td>${money(o.paid)}</td><td>${money(o.due)}</td></tr>`).join("")}</tbody></table></div><h3>Payments</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Bill</th><th>Mode</th><th>Amount</th></tr></thead><tbody>${data.payments.map((p) => `<tr><td>${shortDate(p.receivedAt)}</td><td>${esc(p.order?.billNo || "—")}</td><td>${esc(p.mode)}</td><td>${money(p.amount)}</td></tr>`).join("")}</tbody></table></div>`).querySelectorAll("[data-order]").forEach((row) => row.addEventListener("click", () => showOrder(row.dataset.order))); } catch (error) { notify(error.message); } }

async function renderDirectory(content, type) {
  const config = {
    shops: { api: "/api/admin/shops?all=true", key: "shops", add: "Add shop", headers: ["Shop", "Phone", "Address", "Route", "Status"], fields: ["name", "phone", "address", "route"] },
    routes: { api: "/api/admin/routes?all=true", key: "routes", add: "Add route", headers: ["Route", "Description", "Status"], fields: ["name", "description"] },
    products: { api: "/api/products?includePhotos=true&includeInactive=true", key: "products", add: "Add product", headers: ["Product", "SKU", "Category", "Price", "Display order", "Status"], fields: ["name", "sku", "category", "sellingPrice", "costPrice", "unit", "displayOrder", "photoData"] },
    salesmen: { api: "/api/admin/salesmen?all=true", key: "salesmen", add: "Add salesman", headers: ["Name", "Login", "Routes", "Daily target", "Status"], fields: ["name", "email", "phone", "password", "routes", "dailySalesTarget"] },
  }[type];
  const result = await api(config.api); const rows = result[config.key] || [];
  let table;
  if (type === "shops") table = rows.map((r) => `<tr><td class="product-name">${esc(r.name)}</td><td>${esc(r.phone)}</td><td>${esc(r.address)}</td><td>${esc(r.route?.name || "—")}</td><td><span class="pill ${r.isActive ? "" : "low"}">${r.isActive ? "Active" : "Inactive"}</span></td><td><button class="action" data-edit="${r._id}">Edit</button><button class="action" data-statement="${r._id}">Account</button>${r.isActive ? `<button class="action danger-text" data-deactivate="${r._id}">Deactivate</button>` : ""}</td></tr>`).join("");
  if (type === "routes") table = rows.map((r) => `<tr><td class="product-name">${esc(r.name)}</td><td>${esc(r.description)}</td><td><span class="pill ${r.isActive ? "" : "low"}">${r.isActive ? "Active" : "Inactive"}</span></td><td><button class="action" data-edit="${r._id}">Edit</button>${r.isActive ? `<button class="action danger-text" data-deactivate="${r._id}">Deactivate</button>` : ""}</td></tr>`).join("");
  if (type === "products") { const inventory = await api("/api/inventory"); const stock = new Map((inventory.inventory || []).map((item) => [item.product?._id, item])); table = rows.map((r) => { const item = stock.get(r._id); const qty = item?.quantity || 0; const minimum = item?.lowStockThreshold || 0; return `<tr><td class="product-name">${r.photoData ? `<img class="thumb" src="${r.photoData}" alt="">` : ""}${esc(r.name)}</td><td>${esc(r.sku)}</td><td>${esc(r.category)}</td><td>${money(r.sellingPrice)}</td><td>${r.displayOrder || 0}</td><td><span class="pill ${minimum && qty <= minimum ? "low" : ""}">${num(qty)} ${esc(r.unit)}</span> <button class="action" data-stock="${r._id}" data-stock-name="${esc(r.name)}" data-stock-qty="${qty}" data-stock-min="${minimum}">Adjust</button></td><td><span class="pill ${r.isActive ? "" : "low"}">${r.isActive ? "Active" : "Inactive"}</span></td><td><button class="action" data-edit="${r._id}">Edit</button>${r.isActive ? `<button class="action danger-text" data-deactivate="${r._id}">Deactivate</button>` : ""}</td></tr>`; }).join(""); }
  if (type === "salesmen") table = rows.map((r) => `<tr><td class="product-name">${esc(r.name)}</td><td>${esc(r.email)}<br><small>${esc(r.phone)}</small></td><td>${(r.assignedRoutes || []).map((route) => esc(route.name)).join(", ") || "—"}</td><td>${money(r.dailySalesTarget)}</td><td><span class="pill ${r.isActive ? "" : "low"}">${r.isActive ? "Active" : "Inactive"}</span></td><td><button class="action" data-edit="${r._id}">Edit</button><button class="action" data-reset="${r._id}">Reset password</button>${r.isActive ? `<button class="action danger-text" data-deactivate="${r._id}">Deactivate</button>` : ""}</td></tr>`).join("");
  const importButton = type === "shops" ? `<label class="secondary file-label">Import CSV<input type="file" id="shop-csv" accept=".csv,text/csv" hidden></label>` : "";
  const headers = type === "products" ? [...config.headers.slice(0, 5), "Stock", ...config.headers.slice(5)] : config.headers;
  content.innerHTML = `<div class="section-title"><div><h2>${rows.length} ${type}</h2><p>Deactivated records remain available in old order history.</p></div><div class="toolbar"><input class="search" id="directory-search" placeholder="Search ${type}">${importButton}<button class="primary" data-add>${config.add}</button></div></div><section class="panel table-wrap">${rows.length ? `<table><thead><tr>${headers.map((h) => `<th>${h}</th>`).join("")}<th>Actions</th></tr></thead><tbody>${table}</tbody></table>` : empty(`No ${type} yet`)}</section>`;
  content.querySelector("[data-add]").addEventListener("click", () => directoryModal(type, null));
  content.querySelectorAll("[data-edit]").forEach((b) => b.addEventListener("click", () => directoryModal(type, rows.find((r) => r._id === b.dataset.edit))));
  content.querySelectorAll("[data-deactivate]").forEach((b) => b.addEventListener("click", () => deactivateDirectory(type, b.dataset.deactivate)));
  content.querySelectorAll("[data-statement]").forEach((b) => b.addEventListener("click", () => shopStatement(b.dataset.statement)));
  content.querySelectorAll("[data-reset]").forEach((b) => b.addEventListener("click", () => resetSalesmanPassword(b.dataset.reset)));
  content.querySelectorAll("[data-stock]").forEach((b) => b.addEventListener("click", () => stockModal({ id: b.dataset.stock, name: b.dataset.stockName, quantity: Number(b.dataset.stockQty), threshold: Number(b.dataset.stockMin) })));
  content.querySelector("#directory-search").addEventListener("input", (event) => { const term = event.target.value.toLowerCase(); content.querySelectorAll("tbody tr").forEach((row) => { row.hidden = !row.textContent.toLowerCase().includes(term); }); });
  content.querySelector("#shop-csv")?.addEventListener("change", importShopsCsv);
}

function stockModal(product) { showModal(`<button class="modal-x" data-close>×</button><h2>Adjust ${esc(product.name)} stock</h2><p class="subtle">Current quantity: ${product.quantity}. The balance cannot go below zero.</p><form id="stock-form"><div class="field"><label>Quantity change</label><input name="quantityChange" type="number" step="1" required placeholder="Use a negative value to remove stock"></div><div class="field"><label>Low stock alert at</label><input name="lowStockThreshold" type="number" min="0" step="1" value="${product.threshold}"></div><div class="field"><label>Reason</label><input name="reason" maxlength="200"></div><div class="modal-actions"><button class="secondary" type="button" data-close>Cancel</button><button class="primary">Update inventory</button></div></form>`).querySelector("#stock-form").addEventListener("submit", async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { await api(`/api/inventory/${product.id}/adjustments`, { method: "POST", body: JSON.stringify({ quantityChange: Number(form.get("quantityChange")), lowStockThreshold: Number(form.get("lowStockThreshold")), reason: form.get("reason") }) }); document.querySelector(".modal-backdrop")?.remove(); notify("Stock updated"); await loadPage(); } catch (error) { notify(error.message); } }); }

async function deactivateDirectory(type, id) { if (!confirm("Deactivate this record? Existing order history will be retained.")) return; const path = { shops: "shops", routes: "routes", products: "products", salesmen: "salesmen" }[type]; try { await api(type === "products" ? `/api/products/${id}/status` : `/api/admin/${path}/${id}`, { method: "PATCH", body: JSON.stringify({ isActive: false }) }); notify("Record deactivated"); await loadPage(); } catch (error) { notify(error.message); } }
async function importShopsCsv(event) { const file = event.target.files?.[0]; if (!file) return; try { const result = await api("/api/admin/shops/import", { method: "POST", body: JSON.stringify({ csv: await file.text() }) }); const failed = result.rows.filter((row) => !row.success); notify(`Imported ${result.imported}; ${result.failed} row(s) need attention`); if (failed.length) showModal(`<button class="modal-x" data-close>×</button><h2>CSV import results</h2><p>${result.imported} shops imported. Fix these rows and retry:</p><div class="table-wrap"><table><thead><tr><th>Row</th><th>Reason</th></tr></thead><tbody>${failed.map((r) => `<tr><td>${r.row}</td><td>${esc(r.reason)}</td></tr>`).join("")}</tbody></table></div>`); await loadPage(); } catch (error) { notify(error.message); } event.target.value = ""; }

function directoryModal(type, record) {
  const routeOptions = state.routes.map((r) => `<option value="${r._id}" ${record?.route?._id === r._id ? "selected" : ""}>${esc(r.name)}</option>`).join("");
  let fields = "", endpoint = "", method = record ? "PATCH" : "POST", payload;
  if (type === "shops") { fields = `<div class="field"><label>Name</label><input name="name" required value="${esc(record?.name || "")}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(record?.phone || "")}"></div><div class="field"><label>Address</label><input name="address" value="${esc(record?.address || "")}"></div><div class="field"><label>Route</label><select name="route"><option value="">Unassigned</option>${routeOptions}</select></div><div class="two-col"><div class="field"><label>Map latitude</label><input name="lat" type="number" step="any" value="${record?.location?.lat ?? ""}"></div><div class="field"><label>Map longitude</label><input name="lng" type="number" step="any" value="${record?.location?.lng ?? ""}"></div></div>`; endpoint = `/api/admin/shops${record ? `/${record._id}` : ""}`; payload = (f) => ({ name: f.get("name"), phone: f.get("phone"), address: f.get("address"), route: f.get("route") || null, ...(f.get("lat") !== "" && f.get("lng") !== "" ? { location: { lat: Number(f.get("lat")), lng: Number(f.get("lng")) } } : {}) }); }
  if (type === "routes") { fields = `<div class="field"><label>Name</label><input name="name" required value="${esc(record?.name || "")}"></div><div class="field"><label>Description</label><input name="description" value="${esc(record?.description || "")}"></div>`; endpoint = `/api/admin/routes${record ? `/${record._id}` : ""}`; payload = (f) => ({ name: f.get("name"), description: f.get("description") }); }
  if (type === "products") { fields = `<div class="field"><label>Product name</label><input name="name" required value="${esc(record?.name || "")}"></div><div class="field"><label>SKU</label><input name="sku" required value="${esc(record?.sku || "")}"></div><div class="field"><label>Category</label><input name="category" required value="${esc(record?.category || "")}"></div><div class="field"><label>Unit</label><select name="unit">${["piece", "packet", "kg", "gram", "litre"].map((u) => `<option ${record?.unit === u ? "selected" : ""}>${u}</option>`).join("")}</select></div><div class="two-col"><div class="field"><label>Selling price (₹)</label><input type="number" min="0" step="0.01" name="sellingPrice" required value="${record?.sellingPrice ?? ""}"></div><div class="field"><label>Cost price (₹)</label><input type="number" min="0" step="0.01" name="costPrice" required value="${record?.costPrice ?? ""}"></div></div><div class="field"><label>Salesman display order</label><input type="number" min="0" step="1" name="displayOrder" value="${record?.displayOrder || 0}"></div><div class="field"><label>Product photo</label><input type="file" name="photo" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG or WebP, maximum 4 MB.</small></div>`; endpoint = record ? `/api/products/${record._id}` : "/api/products"; payload = async (f) => { let photoData = record?.photoData || ""; const file = f.get("photo"); if (file?.size) { if (file.size > 4 * 1024 * 1024) throw new Error("Choose an image smaller than 4 MB"); photoData = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(file); }); } return { name: f.get("name"), sku: f.get("sku"), category: f.get("category"), unit: f.get("unit"), sellingPrice: Number(f.get("sellingPrice")), costPrice: Number(f.get("costPrice")), displayOrder: Number(f.get("displayOrder")), photoData }; }; }
  if (type === "salesmen") { fields = `<div class="field"><label>Name</label><input name="name" required value="${esc(record?.name || "")}"></div>${record ? "" : `<div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Initial password</label><input name="password" type="password" minlength="12" required></div>`}<div class="field"><label>Phone</label><input name="phone" value="${esc(record?.phone || "")}"></div><div class="field"><label>Assigned routes</label><select name="routes" multiple size="4">${state.routes.map((r) => `<option value="${r._id}" ${(record?.assignedRoutes || []).some((x) => (x._id || x) === r._id) ? "selected" : ""}>${esc(r.name)}</option>`).join("")}</select><small>Hold Ctrl / Command to select more than one.</small></div><div class="field"><label>Daily sales target (₹)</label><input name="dailySalesTarget" type="number" min="0" value="${record?.dailySalesTarget || 0}"></div>`; endpoint = record ? `/api/admin/salesmen/${record._id}` : "/api/admin/salesmen"; payload = (f) => ({ name: f.get("name"), phone: f.get("phone"), routes: [...f.getAll("routes")], dailySalesTarget: Number(f.get("dailySalesTarget")), ...(!record ? { email: f.get("email"), password: f.get("password") } : {}) }); }
  showModal(`<button class="modal-x" data-close>×</button><h2>${record ? "Edit" : "Add"} ${type === "salesmen" ? "salesman" : type.slice(0, -1)}</h2><p class="subtle">${record ? "Update the active record details." : "Create a record in the bakery workspace."}</p><form id="directory-form">${fields}<div class="modal-actions"><button class="secondary" type="button" data-close>Cancel</button><button class="primary">${record ? "Save changes" : "Create"}</button></div></form>`).querySelector("#directory-form").addEventListener("submit", async (event) => { event.preventDefault(); const button = event.currentTarget.querySelector("button.primary"); button.disabled = true; try { const data = await payload(new FormData(event.currentTarget)); await api(endpoint, { method, body: JSON.stringify(data) }); notify(`${type.slice(0, -1)} saved`); document.querySelector(".modal-backdrop")?.remove(); await loadPage(); } catch (error) { notify(error.message); button.disabled = false; } });
}

function resetSalesmanPassword(id) { showModal(`<button class="modal-x" data-close>×</button><h2>Reset password</h2><form id="reset-form"><div class="field"><label>New password</label><input name="password" type="password" minlength="12" required></div><div class="modal-actions"><button class="secondary" type="button" data-close>Cancel</button><button class="primary">Reset</button></div></form>`).querySelector("#reset-form").addEventListener("submit", async (event) => { event.preventDefault(); try { await api(`/api/admin/salesmen/${id}/reset-password`, { method: "POST", body: JSON.stringify({ password: new FormData(event.currentTarget).get("password") }) }); document.querySelector(".modal-backdrop")?.remove(); notify("Password reset"); } catch (error) { notify(error.message); } }); }

async function renderAttendance(content) { const date = new URLSearchParams(location.search).get("date") || state.day; const result = await api(`/api/admin/attendance?date=${date}`); content.innerHTML = `<div class="section-title"><div><h2>Attendance for ${esc(date)}</h2><p>Salesmen who have not started are included in the list.</p></div></div><section class="panel table-wrap">${result.attendance.length ? `<table><thead><tr><th>Salesman</th><th>Status</th><th>Started</th><th>Ended</th><th>Hours worked</th><th>Starting location</th></tr></thead><tbody>${result.attendance.map((r) => `<tr><td class="product-name">${esc(r.salesman.name)}</td><td><span class="pill ${r.status === "not_started" ? "low" : ""}">${r.status.replaceAll("_", " ")}</span></td><td>${shortDate(r.startedAt)}</td><td>${shortDate(r.endedAt)}</td><td>${r.hoursWorked}</td><td>${r.mapsUrl ? `<a href="${r.mapsUrl}" target="_blank" rel="noopener">Open map ↗</a>` : "—"}</td></tr>`).join("")}</tbody></table>` : empty("No active salesmen")}</section>`; }

const reportLabels = { "sales-by-day": "Sales by day", "sales-by-product": "Sales by product", "sales-by-salesman": "Sales by salesman", "sales-by-shop": "Sales by shop", collections: "Collections" };
async function renderReports(content) { const q = new URLSearchParams(location.search); const report = reportLabels[q.get("report")] ? q.get("report") : "sales-by-day"; const from = q.get("from") || state.day, to = q.get("to") || state.day; const params = new URLSearchParams({ from, to }); if (report === "collections") { if (q.get("mode")) params.set("mode", q.get("mode")); if (q.get("salesman")) params.set("salesman", q.get("salesman")); } const result = await api(`/api/admin/reports/${report}?${params}`); const rows = result.rows || []; const columns = rows.length ? Object.keys(rows[0]).filter((k) => k !== "_id") : []; if (state.reportSort) rows.sort((a,b) => String(a[state.reportSort.key] ?? "").localeCompare(String(b[state.reportSort.key] ?? ""), undefined, { numeric: true, sensitivity: "base" }) * state.reportSort.direction); content.innerHTML = `<form class="panel filters" id="report-filters"><label>Report<select name="report">${Object.entries(reportLabels).map(([key,label]) => `<option value="${key}" ${report === key ? "selected" : ""}>${label}</option>`).join("")}</select></label><label>From<input type="date" name="from" value="${esc(from)}"></label><label>To<input type="date" name="to" value="${esc(to)}"></label>${report === "collections" ? `<label>Mode<select name="mode"><option value="">All</option><option value="cash" ${q.get("mode") === "cash" ? "selected" : ""}>Cash</option><option value="upi" ${q.get("mode") === "upi" ? "selected" : ""}>UPI</option></select></label>` : ""}<button class="primary">Run report</button><button class="secondary" type="button" data-export="csv">Download CSV</button><button class="secondary" type="button" data-export="xls">Download Excel</button></form><section class="panel table-wrap">${rows.length ? `<table id="report-table"><thead><tr>${columns.map((c) => `<th data-sort="${esc(c)}">${esc(c)} ↕</th>`).join("")}</tr></thead><tbody>${rows.map((row) => `<tr>${columns.map((col) => `<td>${col === "inactive7Days" ? (row[col] ? '<span class="pill low">No order 7+ days</span>' : '<span class="pill">Recent</span>') : esc(row[col] instanceof Date ? row[col].toISOString() : row[col])}</td>`).join("")}</tr>`).join("")}</tbody>${rows.some((r) => columns.some((c) => typeof r[c] === "number")) ? `<tfoot><tr>${columns.map((col, index) => { const values = rows.map((row) => row[col]).filter((value) => typeof value === "number"); return `<th>${values.length ? (col.toLowerCase().includes("sales") || col === "collected" || col === "paid" || col === "due" || col === "amount" ? money(values.reduce((a,b) => a + b, 0)) : num(values.reduce((a,b) => a + b, 0))) : index === 0 ? "Total" : ""}</th>`; }).join("")}</tr></tfoot>` : ""}</table>` : empty("No rows for this date range")}</section>`;
  content.querySelector("#report-filters").addEventListener("submit", (e) => { e.preventDefault(); const p = new URLSearchParams(new FormData(e.currentTarget)); for (const [k,v] of [...p]) if (!v) p.delete(k); history.pushState({}, "", `/?page=reports&${p}`); loadPage(); });
  content.querySelectorAll("[data-export]").forEach((button) => button.addEventListener("click", () => downloadReport(rows, columns, report, button.dataset.export)));
  content.querySelectorAll("th[data-sort]").forEach((th) => th.addEventListener("click", () => { const key = th.dataset.sort; const direction = state.reportSort?.key === key ? -state.reportSort.direction : 1; state.reportSort = { key, direction }; renderReports(content).catch((e) => notify(e.message)); }));
}

function downloadReport(rows, columns, name, format) { let content, type, ext; if (format === "csv") { const cell = (v) => { let safe = String(v ?? ""); if (/^[=+\-@\t\r]/.test(safe)) safe = `'${safe}`; return `"${safe.replaceAll('"', '""')}"`; }; content = `\uFEFF${[columns.map(cell).join(","), ...rows.map((r) => columns.map((c) => cell(r[c])).join(","))].join("\r\n")}`; type = "text/csv;charset=utf-8"; ext = "csv"; } else { const escXml = (v) => esc(v); content = `<html><head><meta charset="utf-8"></head><body><table><thead><tr>${columns.map((c) => `<th>${escXml(c)}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${columns.map((c) => `<td>${escXml(r[c])}</td>`).join("")}</tr>`).join("")}</tbody></table></body></html>`; type = "application/vnd.ms-excel"; ext = "xls"; } const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([content], { type })); a.download = `${name}.${ext}`; a.click(); URL.revokeObjectURL(a.href); }

async function renderProduction(content) { const date = new URLSearchParams(location.search).get("date") || state.day; const [planData, products] = await Promise.all([api(`/api/admin/production/${date}`), api("/api/products")]); const plan = planData.plan; const lines = plan?.lines || []; content.innerHTML = `<div class="section-title"><div><h2>Production plan</h2><p>Set the bake plan and record actual output and wastage.</p></div><label class="date-chip">Day <input id="plan-date" type="date" value="${esc(date)}"></label></div><form class="panel" id="plan-form"><div class="table-wrap"><table><thead><tr><th>Product</th><th>Planned</th><th>Baked</th><th>Wasted</th></tr></thead><tbody>${products.products.map((p) => { const line = lines.find((item) => (item.product?._id || item.product) === p._id); return `<tr><td class="product-name">${esc(p.name)}</td><td><input type="number" min="0" step="1" name="planned:${p._id}" value="${line?.planned ?? 0}"></td><td><input type="number" min="0" step="1" name="baked:${p._id}" value="${line?.baked ?? 0}"></td><td><input type="number" min="0" step="1" name="wasted:${p._id}" value="${line?.wasted ?? 0}"></td></tr>`; }).join("")}</tbody></table></div><div class="modal-actions"><button class="primary">Save production plan</button></div></form>`;
  content.querySelector("#plan-date").addEventListener("change", (e) => { history.pushState({}, "", `/?page=production&date=${e.target.value}`); loadPage(); });
  content.querySelector("#plan-form").addEventListener("submit", async (e) => { e.preventDefault(); const f = new FormData(e.currentTarget); const lines = products.products.map((p) => ({ product: p._id, planned: Number(f.get(`planned:${p._id}`)), baked: Number(f.get(`baked:${p._id}`)), wasted: Number(f.get(`wasted:${p._id}`)) })).filter((l) => l.planned || l.baked || l.wasted); try { await api(`/api/admin/production/${date}`, { method: "PUT", body: JSON.stringify({ lines }) }); notify("Production plan saved"); await loadPage(); } catch (error) { notify(error.message); } }); }

async function renderMaterials(content) { const { materials } = await api("/api/admin/raw-materials?all=true"); content.innerHTML = `<div class="section-title"><div><h2>${materials.length} raw materials</h2><p>Materials at or below minimum appear on the dashboard factory strip.</p></div><button class="primary" data-add-material>Add material</button></div><section class="panel table-wrap">${materials.length ? `<table><thead><tr><th>Name</th><th>SKU</th><th>Unit</th><th>On hand</th><th>Minimum</th><th>Status</th><th></th></tr></thead><tbody>${materials.map((m) => `<tr><td class="product-name">${esc(m.name)}</td><td>${esc(m.sku)}</td><td>${esc(m.unit)}</td><td>${num(m.onHand)}</td><td>${num(m.minimumLevel)}</td><td><span class="pill ${m.onHand <= m.minimumLevel ? "low" : ""}">${m.onHand <= m.minimumLevel ? "Restock" : "OK"}</span></td><td><button class="action" data-material="${m._id}" data-name="${esc(m.name)}" data-onhand="${m.onHand}" data-minimum="${m.minimumLevel}">Edit stock</button></td></tr>`).join("")}</tbody></table>` : empty("No raw materials tracked")}</section>`;
  content.querySelector("[data-add-material]").addEventListener("click", () => materialModal()); content.querySelectorAll("[data-material]").forEach((b) => b.addEventListener("click", () => materialModal({ id: b.dataset.material, name: b.dataset.name, onHand: Number(b.dataset.onhand), minimumLevel: Number(b.dataset.minimum) })));
}
function materialModal(material) { const editing = material?.id; showModal(`<button class="modal-x" data-close>×</button><h2>${editing ? "Update" : "Add"} raw material</h2><form id="material-form">${editing ? "" : `<div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>SKU</label><input name="sku" required></div><div class="field"><label>Unit</label><input name="unit" required placeholder="kg, bag, litre"></div>`}<div class="field"><label>On hand</label><input name="onHand" type="number" min="0" step="any" required value="${material?.onHand ?? 0}"></div><div class="field"><label>Minimum level</label><input name="minimumLevel" type="number" min="0" step="any" required value="${material?.minimumLevel ?? 0}"></div><div class="modal-actions"><button class="secondary" type="button" data-close>Cancel</button><button class="primary">Save</button></div></form>`).querySelector("#material-form").addEventListener("submit", async (e) => { e.preventDefault(); const f = new FormData(e.currentTarget), body = { onHand: Number(f.get("onHand")), minimumLevel: Number(f.get("minimumLevel")) }; if (!editing) Object.assign(body, { name: f.get("name"), sku: f.get("sku"), unit: f.get("unit") }); try { await api(editing ? `/api/admin/raw-materials/${material.id}` : "/api/admin/raw-materials", { method: editing ? "PATCH" : "POST", body: JSON.stringify(body) }); document.querySelector(".modal-backdrop")?.remove(); notify("Raw material saved"); await loadPage(); } catch (error) { notify(error.message); } }); }

function bindShared() { root.querySelectorAll("[data-go]").forEach((button) => button.addEventListener("click", () => navigate(button.dataset.go))); }

function loginInit() { if (state.token) { root.innerHTML = `<div class="loading">Opening your admin workspace…</div>`; initialize(); } else login(); }
loginInit();
